+            input.select();
+          }}>Edit your search</button
+        >
+      </div>
+    {:else}
+      <div class="results-heading">
+        <h2>
+          {searchState.entities.length}
+          {searchState.entities.length === 1 ? "result" : "results"} shown
+        </h2>
