diff --git a/exposed/src/lib/inbound/http/handlers/entity_details.rs b/exposed/src/lib/inbound/http/handlers/entity_details.rs
new file mode 100644
index 0000000..57ce287
--- /dev/null
+++ b/exposed/src/lib/inbound/http/handlers/entity_details.rs
@@ -0,0 +1,242 @@
+use crate::{
+    domain::{
+        models::{
+            entity_details::{
+                CurrencyBreakdown, DeclaredFunding, FunderDetails, FunderProfile, FunderReference,
+                MemberDetails, MemberProfile, PartyTotal, RecentDeclaration, RecipientAllocation,
+            },
+            funder::FunderId,
+            parliament_member::MemberId,
+        },
+        services::{
+            entity_details::{EntityDetailsError, EntityDetailsService},
+            entity_search::EntitySearchService,
+        },
+    },
+    inbound::http::{error::ApiError, state::AppState, success::ApiSuccess},
+};
+use axum::{
+    extract::{Path, State},
+    http::StatusCode,
+};
+use chrono::{DateTime, Utc};
+use serde::Serialize;
+
+impl From<EntityDetailsError> for ApiError {
+    fn from(error: EntityDetailsError) -> Self {
+        match error {
+            EntityDetailsError::NotFound => Self::NotFound,
+            EntityDetailsError::Unexpected(_) => Self::InternalServerError,
+        }
+    }
+}
+
+#[derive(Serialize)]
+pub struct MemberResponse {
+    id: String,
+    name: String,
+    party_id: i32,
+    party_name: String,
+    constituency: String,
+    is_current_commons: bool,
+}
+impl From<MemberProfile> for MemberResponse {
+    fn from(member: MemberProfile) -> Self {
+        Self {
+            id: member.id.value().to_string(),
+            name: member.name,
+            party_id: member.party_id,
+            party_name: member.party_name,
+            constituency: member.constituency,
+            is_current_commons: member.is_current_commons,
+        }
+    }
+}
+
+#[derive(Serialize)]
+pub struct FunderReferenceResponse {
+    id: String,
+    name: String,
+}
+impl From<FunderReference> for FunderReferenceResponse {
+    fn from(funder: FunderReference) -> Self {
+        Self {
+            id: funder.id.value().to_string(),
+            name: funder.name,
+        }
+    }
+}
+
+#[derive(Serialize)]
+pub struct FundingResponse {
+    funder: Option<FunderReferenceResponse>,
+    amount: Option<String>,
+    currency: Option<String>,
+    payment_type: Option<String>,
+}
+impl From<DeclaredFunding> for FundingResponse {
+    fn from(entry: DeclaredFunding) -> Self {
+        Self {
+            funder: entry.funder.map(Into::into),
+            amount: entry
+                .amount
+                .map(|amount| amount.normalized().to_plain_string()),
+            currency: entry.currency,
+            payment_type: entry.payment_type,
+        }
+    }
+}
+
+#[derive(Serialize)]
+pub struct DeclarationResponse {
+    source_id: i32,
+    category_name: String,
+    registered_at: Option<DateTime<Utc>>,
+    entries: Vec<FundingResponse>,
+}
+impl From<RecentDeclaration> for DeclarationResponse {
+    fn from(declaration: RecentDeclaration) -> Self {
+        Self {
+            source_id: declaration.source_id,
+            category_name: declaration.category_name,
+            registered_at: declaration.registered_at,
+            entries: declaration.entries.into_iter().map(Into::into).collect(),
+        }
+    }
+}
+
+#[derive(Serialize)]
+pub struct MemberDetailsResponse {
+    member: MemberResponse,
+    declarations: Vec<DeclarationResponse>,
+    declaration_count: i64,
+    declaration_limit: usize,
+}
+impl From<MemberDetails> for MemberDetailsResponse {
+    fn from(details: MemberDetails) -> Self {
+        Self {
+            member: details.member.into(),
+            declarations: details.declarations.into_iter().map(Into::into).collect(),
+            declaration_count: details.declaration_count,
+            declaration_limit: details.declaration_limit,
+        }
+    }
+}
+
+#[derive(Serialize)]
+pub struct FunderResponse {
+    id: String,
+    name: String,
+    funder_kind: String,
+    company_number: Option<String>,
+}
+impl From<FunderProfile> for FunderResponse {
+    fn from(profile: FunderProfile) -> Self {
+        Self {
+            id: profile.funder.id().value().to_string(),
+            name: profile.funder.name().to_string(),
+            funder_kind: profile.funder.kind().to_string(),
+            company_number: profile.company_number,
+        }
+    }
+}
+
+#[derive(Serialize)]
+pub struct PartyTotalResponse {
+    party_id: i32,
+    party_name: String,
+    amount: Option<String>,
+    entry_count: i64,
+    unknown_amount_count: i64,
+}
+impl From<PartyTotal> for PartyTotalResponse {
+    fn from(party: PartyTotal) -> Self {
+        Self {
+            party_id: party.party_id,
+            party_name: party.party_name,
+            amount: party
+                .amount
+                .map(|amount| amount.normalized().to_plain_string()),
+            entry_count: party.entry_count,
+            unknown_amount_count: party.unknown_amount_count,
+        }
+    }
+}
+
+#[derive(Serialize)]
+pub struct RecipientTotalResponse {
+    member: MemberResponse,
+    amount: Option<String>,
+    entry_count: i64,
+    unknown_amount_count: i64,
+}
+impl From<RecipientAllocation> for RecipientTotalResponse {
+    fn from(recipient: RecipientAllocation) -> Self {
+        Self {
+            member: recipient.member.into(),
+            amount: recipient
+                .known_total
+                .map(|amount| amount.normalized().to_plain_string()),
+            entry_count: recipient.entry_count,
+            unknown_amount_count: recipient.unknown_amount_count,
+        }
+    }
+}
+
+#[derive(Serialize)]
+pub struct CurrencyResponse {
+    currency: String,
+    parties: Vec<PartyTotalResponse>,
+    top_recipients: Vec<RecipientTotalResponse>,
+}
+impl From<CurrencyBreakdown> for CurrencyResponse {
+    fn from(group: CurrencyBreakdown) -> Self {
+        Self {
+            currency: group.currency,
+            parties: group.parties.into_iter().map(Into::into).collect(),
+            top_recipients: group.top_recipients.into_iter().map(Into::into).collect(),
+        }
+    }
+}
+
+#[derive(Serialize)]
+pub struct FunderDetailsResponse {
+    funder: FunderResponse,
+    currencies: Vec<CurrencyResponse>,
+    entry_count: i64,
+    unknown_currency_count: i64,
+    recipient_limit: usize,
+}
+impl From<FunderDetails> for FunderDetailsResponse {
+    fn from(details: FunderDetails) -> Self {
+        Self {
+            funder: details.profile.into(),
+            currencies: details.currencies.into_iter().map(Into::into).collect(),
+            entry_count: details.entry_count,
+            unknown_currency_count: details.unknown_currency_count,
+            recipient_limit: details.recipient_limit,
+        }
+    }
+}
+
+pub async fn member_details<E: EntitySearchService, D: EntityDetailsService>(
+    State(state): State<AppState<E, D>>,
+    Path(id): Path<String>,
+) -> Result<ApiSuccess<MemberDetailsResponse>, ApiError> {
+    let id = id
+        .parse::<MemberId>()
+        .map_err(ApiError::UnprocessibleEntity)?;
+    let details = state.entity_details_service.member(id).await?;
+    Ok(ApiSuccess::new(StatusCode::OK, details.into()))
+}
+
+pub async fn funder_details<E: EntitySearchService, D: EntityDetailsService>(
+    State(state): State<AppState<E, D>>,
+    Path(id): Path<String>,
+) -> Result<ApiSuccess<FunderDetailsResponse>, ApiError> {
+    let id = id
+        .parse::<FunderId>()
+        .map_err(|_| ApiError::UnprocessibleEntity("Invalid funder ID".into()))?;
+    let details = state.entity_details_service.funder(id).await?;
+    Ok(ApiSuccess::new(StatusCode::OK, details.into()))
+}
diff --git a/frontend/src/SearchPage.svelte b/frontend/src/SearchPage.svelte
new file mode 100644
index 0000000..afbe788
--- /dev/null
+++ b/frontend/src/SearchPage.svelte
@@ -0,0 +1,328 @@
+<script lang="ts">
+  import Icon from "./lib/Icon.svelte";
+  import EntityIndicator from "./lib/EntityIndicator.svelte";
+  import {
+    entityHref,
+    highlightName,
+    readStrictness,
+    searchConfiguration,
+    searchEntities,
+    type Entity,
+  } from "./lib/search";
+
+  type SearchState =
+    | { status: "idle" }
+    | { status: "loading"; term: string }
+    | { status: "success"; term: string; entities: Entity[] }
+    | { status: "error"; term: string; message: string };
+
+  let query = $state(new URL(window.location.href).searchParams.get("q") ?? "");
+  let strictness = $state(
+    readStrictness(
+      new URL(window.location.href).searchParams.get("strictness"),
+    ),
+  );
+  let composing = $state(false);
+  let attempt = $state(0);
+  let input: HTMLInputElement;
+  let searchState = $state<SearchState>({ status: "idle" });
+  const term = $derived(query.trim());
+  const charactersNeeded = $derived(
+    Math.max(0, searchConfiguration.minimumCharacters - [...term].length),
+  );
+  const announcement = $derived(
+    searchState.status === "loading"
+      ? "Searching…"
+      : searchState.status === "success"
+        ? `${searchState.entities.length} ${searchState.entities.length === 1 ? "result" : "results"} shown for ${searchState.term}.`
+        : "",
+  );
+
+  $effect(() => {
+    const currentTerm = term;
+    const currentStrictness = strictness;
+    const currentAttempt = attempt;
+    if (
+      composing ||
+      [...currentTerm].length < searchConfiguration.minimumCharacters
+    ) {
+      searchState = { status: "idle" };
+      return;
+    }
+
+    const controller = new AbortController();
+    let current = true;
+    searchState = { status: "loading", term: currentTerm };
+    const timer = setTimeout(
+      async () => {
+        try {
+          const entities = await searchEntities(
+            currentTerm,
+            controller.signal,
+            currentStrictness,
+          );
+          if (current)
+            searchState = { status: "success", term: currentTerm, entities };
+        } catch (error) {
+          if (current)
+            searchState = {
+              status: "error",
+              term: currentTerm,
+              message:
+                error instanceof Error
+                  ? error.message
+                  : "Search couldn’t load. Try again.",
+            };
+        }
+      },
+      currentAttempt > 0 ? 0 : searchConfiguration.debounceMs,
+    );
+
+    return () => {
+      current = false;
+      clearTimeout(timer);
+      controller.abort();
+    };
+  });
+
+  function updateQuery(value: string) {
+    attempt = 0;
+    query = value;
+    const url = new URL(window.location.href);
+    if (value.trim()) url.searchParams.set("q", value.trim());
+    else url.searchParams.delete("q");
+    window.history.replaceState(null, "", url);
+  }
+
+  function updateStrictness(value: string) {
+    attempt = 0;
+    strictness = readStrictness(value);
+    const url = new URL(window.location.href);
+    url.searchParams.set("strictness", String(strictness));
+    window.history.replaceState(null, "", url);
+  }
+
+  function clearSearch() {
+    updateQuery("");
+    input.focus();
+  }
+
+  function shortcut(event: KeyboardEvent) {
+    const target = event.target;
+    const editing =
+      target instanceof HTMLElement &&
+      (target.isContentEditable ||
+        ["INPUT", "TEXTAREA", "SELECT"].includes(target.tagName));
+    if (
+      event.key === "/" &&
+      !editing &&
+      !event.ctrlKey &&
+      !event.metaKey &&
+      !event.altKey
+    ) {
+      event.preventDefault();
+      input.focus();
+    }
+    if (event.key === "Escape" && target === input && !event.isComposing)
+      clearSearch();
+  }
+
+  function atLimit(entities: Entity[]) {
+    return ["MP", "Funder"].some(
+      (kind) =>
+        entities.filter((entity) => entity.kind === kind).length >=
+        searchConfiguration.maxEntriesPerType,
+    );
+  }
+</script>
+
+<svelte:window
+  onkeydown={shortcut}
+  onpopstate={() => {
+    const params = new URL(window.location.href).searchParams;
+    query = params.get("q") ?? "";
+    strictness = readStrictness(params.get("strictness"));
+    attempt = 0;
+  }}
+/>
+
+<main id="search">
+  <div class="search-intro">
+    <h1>Search MPs and funders</h1>
+    <p>Find a name in the Register of Members’ Financial Interests.</p>
+  </div>
+
+  <form
+    role="search"
+    onsubmit={(event) => {
+      event.preventDefault();
+      if (!composing && !charactersNeeded) attempt += 1;
+    }}
+  >
+    <label class="visually-hidden" for="entity-search"
+      >Search MPs and funders</label
+    >
+    <div class="search-field">
+      <span class="search-icon"><Icon name="search" size={24} /></span>
+      <input
+        id="entity-search"
+        type="search"
+        bind:this={input}
+        value={query}
+        oninput={(event) => updateQuery(event.currentTarget.value)}
+        oncompositionstart={() => (composing = true)}
+        oncompositionend={() => (composing = false)}
+        placeholder="Enter an MP or funder’s name"
+        autocomplete="off"
+        spellcheck="false"
+        aria-describedby="search-help"
+      />
+      {#if query}
+        <button
+          class="clear-button"
+          type="button"
+          aria-label="Clear search"
+          onclick={clearSearch}><Icon name="close" size={18} /></button
+        >
+      {:else}
+        <kbd class="search-shortcut" aria-hidden="true">/</kbd>
+      {/if}
+    </div>
+    <p class="search-help" id="search-help">
+      {#if term && charactersNeeded}
+        Type {charactersNeeded} more {charactersNeeded === 1
+          ? "character"
+          : "characters"} to search.
+      {:else if !term}
+        Search by name. Results appear as you type.
+      {:else}
+        MPs and funders, ordered by the closest name match.
+      {/if}
+    </p>
+    <div class="threshold-control">
+      <div class="threshold-label">
+        <label for="similarity-threshold">Similarity threshold</label>
+        <output for="similarity-threshold">{strictness.toFixed(2)}</output>
+      </div>
+      <input
+        id="similarity-threshold"
+        type="range"
+        min="0"
+        max="1"
+        step="0.01"
+        value={strictness}
+        oninput={(event) => updateStrictness(event.currentTarget.value)}
+        aria-describedby="threshold-help"
+      />
+      <div class="threshold-scale" aria-hidden="true">
+        <span>Broader matches</span><span>Closer matches</span>
+      </div>
+      <p id="threshold-help">
+        Lower the threshold to include less similar names.
+      </p>
+    </div>
+  </form>
+
+  <p
+    class="visually-hidden"
+    role="status"
+    aria-live="polite"
+    aria-atomic="true"
+  >
+    {announcement}
+  </p>
+  <section
+    class="results-region"
+    aria-label="Search results"
+    aria-busy={searchState.status === "loading"}
+  >
+    {#if searchState.status === "idle"}
+      <div class="starting-state">
+        <div class="start-symbol" aria-hidden="true">
+          <Icon name="search" size={27} />
+        </div>
+        <h2>Start with a name</h2>
+        <p>Look up an MP, a company, or an individual funder.</p>
+        <div class="examples">
+          <span>Try searching</span>{#each ["John", "HSBC"] as example}<button
+              type="button"
+              onclick={() => {
+                updateQuery(example);
+                input.focus();
+              }}>{example}</button
+            >{/each}
+        </div>
+      </div>
+    {:else if searchState.status === "loading"}
+      <div class="results-heading">
+        <h2>Searching</h2>
+        <span class="loading-indicator" aria-hidden="true"></span>
+      </div>
+      <div class="loading-rows" aria-hidden="true">
+        {#each [60, 44, 72, 53] as width}<div class="loading-row">
+            <span class="skeleton-icon"></span><span
+              class="skeleton-name"
+              style:width={`${width}%`}
+            ></span>
+          </div>{/each}
+      </div>
+    {:else if searchState.status === "error"}
+      <div class="message-state" role="alert">
+        <span class="state-icon"><Icon name="retry" size={24} /></span>
+        <h2>Search couldn’t load</h2>
+        <p>{searchState.message}</p>
+        <button
+          class="retry-button"
+          type="button"
+          onclick={() => (attempt += 1)}
+          ><Icon name="retry" size={16} />Try again</button
+        >
+      </div>
+    {:else if searchState.entities.length === 0}
+      <div class="message-state">
+        <span class="state-icon"><Icon name="search" size={24} /></span>
+        <h2>No matches for “{searchState.term}”</h2>
+        <p>Try a surname, a shorter company name, or a different spelling.</p>
+        <button
+          class="text-button"
