-- Date-only source values are stored at midnight UTC.
CREATE SCHEMA IF NOT EXISTS exposed;
CREATE EXTENSION IF NOT EXISTS pg_trgm WITH SCHEMA exposed;

CREATE TABLE IF NOT EXISTS exposed.parliament_terms (
    id UUID PRIMARY KEY DEFAULT uuidv7(),
    term_start TIMESTAMPTZ NOT NULL UNIQUE,
    term_end TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT parliament_terms_valid_dates
        CHECK (term_end IS NULL OR term_end >= term_start)
);

CREATE TABLE IF NOT EXISTS exposed.members (
    id UUID PRIMARY KEY DEFAULT uuidv7(),
    parliament_member_id INTEGER NOT NULL UNIQUE CHECK (parliament_member_id > 0),
    name TEXT NOT NULL CHECK (length(trim(name)) > 0),
    party_id INTEGER NOT NULL,
    party_name TEXT NOT NULL,
    latest_house SMALLINT NOT NULL CHECK (latest_house IN (1, 2)),
    latest_membership_from TEXT NOT NULL,
    is_current_commons BOOLEAN NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (NOT is_current_commons OR latest_house = 1)
);

CREATE TABLE IF NOT EXISTS exposed.member_terms (
    id UUID PRIMARY KEY DEFAULT uuidv7(),
    member_id UUID NOT NULL REFERENCES exposed.members (id),
    term_id UUID NOT NULL REFERENCES exposed.parliament_terms (id),
    house SMALLINT NOT NULL CHECK (house IN (1, 2)),
    source_start_date TIMESTAMPTZ NOT NULL,
    source_end_date TIMESTAMPTZ,
    served_from TIMESTAMPTZ NOT NULL,
    served_until TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (member_id, term_id, house, source_start_date),
    CHECK (served_from >= source_start_date),
    CHECK (served_until IS NULL OR served_until >= served_from),
    CHECK (served_until IS NOT DISTINCT FROM source_end_date)
);

CREATE INDEX IF NOT EXISTS member_terms_term_idx
    ON exposed.member_terms (term_id);

CREATE OR REPLACE FUNCTION exposed.check_term_service_start()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    IF NEW.served_from IS DISTINCT FROM (
        SELECT greatest(NEW.source_start_date, term_start)
        FROM exposed.parliament_terms
        WHERE id = NEW.term_id
    ) THEN
        RAISE EXCEPTION 'Service start must be the later of source start and term start'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;

CREATE OR REPLACE TRIGGER member_terms_check_start
    BEFORE INSERT OR UPDATE ON exposed.member_terms
    FOR EACH ROW
    EXECUTE FUNCTION exposed.check_term_service_start();

CREATE TABLE IF NOT EXISTS exposed.declarations (
    id UUID PRIMARY KEY DEFAULT uuidv7(),
    source_declaration_id INTEGER NOT NULL UNIQUE CHECK (source_declaration_id > 0),
    member_id UUID NOT NULL REFERENCES exposed.members (id),
    category_id INTEGER NOT NULL CHECK (category_id > 0),
    category_name TEXT NOT NULL CHECK (length(trim(category_name)) > 0),
    fetched_at TIMESTAMPTZ NOT NULL,
    registration_date TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS declarations_member_idx
    ON exposed.declarations (member_id);

COMMENT ON COLUMN exposed.declarations.registration_date IS
    'Parliament registrationDate at midnight UTC from the latest selected register version; NULL when unavailable';

CREATE TABLE IF NOT EXISTS exposed.funders (
    id UUID PRIMARY KEY DEFAULT uuidv7(),
    funder_name TEXT NOT NULL UNIQUE,
    funder_kind TEXT,
    company_number TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT funders_company_number_status
        CHECK (company_number IS NULL OR funder_kind IS NOT DISTINCT FROM 'Company')
);

COMMENT ON COLUMN exposed.funders.funder_kind IS
    'Explicit Parliament DonorStatus for the attributed donor; NULL when unavailable';
COMMENT ON COLUMN exposed.funders.company_number IS
    'Parliament DonorCompanyIdentifier when DonorStatus is Company; text preserves leading zeros';

CREATE TABLE IF NOT EXISTS exposed.funding_entries (
    id UUID PRIMARY KEY DEFAULT uuidv7(),
    source_declaration_id INTEGER NOT NULL REFERENCES exposed.declarations (source_declaration_id),
    funder_id UUID REFERENCES exposed.funders (id),
    amount NUMERIC,
    currency TEXT,
    payment_type TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS funding_entries_declaration_idx
    ON exposed.funding_entries (source_declaration_id);
CREATE INDEX IF NOT EXISTS funding_entries_funder_idx
    ON exposed.funding_entries (funder_id);

COMMENT ON COLUMN exposed.funding_entries.funder_id IS
    'Shared exact-name funder; NULL when the source does not identify a funder';

CREATE OR REPLACE FUNCTION exposed.set_updated_at()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    NEW.updated_at := now();

    RETURN NEW;
END;
$$;

CREATE OR REPLACE TRIGGER parliament_terms_set_updated_at
    BEFORE UPDATE ON exposed.parliament_terms
    FOR EACH ROW
    WHEN (OLD.* IS DISTINCT FROM NEW.*)
    EXECUTE FUNCTION exposed.set_updated_at();

CREATE OR REPLACE TRIGGER members_set_updated_at
    BEFORE UPDATE ON exposed.members
    FOR EACH ROW
    WHEN (OLD.* IS DISTINCT FROM NEW.*)
    EXECUTE FUNCTION exposed.set_updated_at();

CREATE OR REPLACE TRIGGER member_terms_set_updated_at
    BEFORE UPDATE ON exposed.member_terms
    FOR EACH ROW
    WHEN (OLD.* IS DISTINCT FROM NEW.*)
    EXECUTE FUNCTION exposed.set_updated_at();

CREATE OR REPLACE TRIGGER declarations_set_updated_at
    BEFORE UPDATE ON exposed.declarations
    FOR EACH ROW
    WHEN (OLD.* IS DISTINCT FROM NEW.*)
    EXECUTE FUNCTION exposed.set_updated_at();

CREATE OR REPLACE TRIGGER funding_entries_set_updated_at
    BEFORE UPDATE ON exposed.funding_entries
    FOR EACH ROW
    WHEN (OLD.* IS DISTINCT FROM NEW.*)
    EXECUTE FUNCTION exposed.set_updated_at();

CREATE OR REPLACE TRIGGER funders_set_updated_at
    BEFORE UPDATE ON exposed.funders
    FOR EACH ROW
    WHEN (OLD.* IS DISTINCT FROM NEW.*)
    EXECUTE FUNCTION exposed.set_updated_at();
use crate::{
    domain::{
        models::{funder::FunderId, parliament_member::MemberId},
        repositories::entity_details::EntityDetailsRepo,
        services::entity_details::{EntityDetailsError, EntityDetailsService, Service},
    },
    outbound::postgres::ExposedDatabase,
};
use bigdecimal::BigDecimal;
use sqlx::PgPool;

const FUNDER: &str = "10000000-0000-0000-0000-000000000001";

#[sqlx::test(migrations = "../db/migrations", fixtures("details"))]
async fn recent_window_preserves_occurrences_and_empty_declarations(pool: PgPool) {
    let db = ExposedDatabase::from(pool);
    let service = Service::new(db);
    let details = service.member("1".parse().unwrap()).await.unwrap();
    assert_eq!(details.declaration_count, 23);
    assert_eq!(details.declaration_limit, 20);
    assert_eq!(
        details
            .declarations
            .iter()
            .map(|declaration| declaration.source_id)
            .collect::<Vec<_>>(),
        (101..=120).rev().collect::<Vec<_>>()
    );
    assert_eq!(details.declarations[0].entries.len(), 7);
    let duplicate = details.declarations[0]
        .entries
        .iter()
        .filter(|entry| {
            entry.amount == Some("9007199254740993.123456789".parse::<BigDecimal>().unwrap())
        })
        .count();
    assert_eq!(duplicate, 2);
    assert!(
        details.declarations[0]
            .entries
            .iter()
            .any(|entry| entry.funder.is_none()
                && entry.amount.is_none()
                && entry.currency.is_none())
    );
    assert!(
        details.declarations[1..]
            .iter()
            .all(|declaration| declaration.entries.is_empty())
    );
    let details = service.member("2".parse().unwrap()).await.unwrap();
    assert_eq!(
        details
            .declarations
            .iter()
            .map(|declaration| declaration.source_id)
            .collect::<Vec<_>>(),
        vec![202, 201, 200]
    );
    assert!(details.declarations[2].registered_at.is_none());
    assert!(details.declarations[0].registered_at.is_some());
    assert!(
        service
            .member("3".parse().unwrap())
            .await
            .unwrap()
            .declarations
            .is_empty()
    );
    assert!(matches!(
        service.member("999".parse().unwrap()).await,
        Err(EntityDetailsError::NotFound)
    ));
}

#[sqlx::test(migrations = "../db/migrations", fixtures("details"))]
async fn exact_summaries_exclude_unknown_currencies_and_keep_local_coverage(pool: PgPool) {
    let db = ExposedDatabase::from(pool);
    let raw = db
        .funder_funding(FUNDER.parse().unwrap())
        .await
        .unwrap()
        .unwrap();
    assert!(
        raw.allocations
            .iter()
            .filter(|allocation| allocation.currency.is_none())
            .all(|allocation| allocation.known_total.is_none())
    );
    let details = Service::new(db)
        .funder(FUNDER.parse().unwrap())
        .await
        .unwrap();
    assert_eq!(details.profile.company_number.as_deref(), Some("00123456"));
    assert_eq!(details.entry_count, 22);
    assert_eq!(details.unknown_currency_count, 3);
    assert_eq!(
        details
            .currencies
            .iter()
            .map(|group| group.currency.as_str())
            .collect::<Vec<_>>(),
        vec!["EUR", "GBP", "USD"]
    );
    let eur = &details.currencies[0];
    assert!(eur.parties[0].amount.is_none());
    assert_eq!(eur.parties[0].unknown_amount_count, 1);
    assert!(eur.top_recipients[0].known_total.is_none());
    let gbp = &details.currencies[1];
    assert_eq!(
        gbp.parties[0].amount,
        Some("18014398509481998.246913578".parse::<BigDecimal>().unwrap())
    );
    assert_eq!(gbp.parties[0].entry_count, 15);
    assert_eq!(gbp.parties[0].unknown_amount_count, 1);
    assert_eq!(
        gbp.parties[1].amount,
        Some("-5".parse::<BigDecimal>().unwrap())
    );
    assert_eq!(gbp.parties[1].unknown_amount_count, 0);
    assert_eq!(gbp.top_recipients.len(), 10);
    assert_eq!(
        gbp.top_recipients[0].known_total,
        Some("18014398509481986.246913578".parse::<BigDecimal>().unwrap())
    );
    assert_eq!(gbp.top_recipients[0].unknown_amount_count, 1);
    assert_eq!(
        gbp.top_recipients
            .iter()
            .map(|allocation| allocation.member.id.value())
            .collect::<Vec<_>>(),
        vec![1, 4, 5, 6, 7, 8, 9, 10, 11, 12]
    );
    assert_eq!(details.currencies[2].top_recipients[0].member.id.value(), 2);
    assert_eq!(
        details.currencies[2].parties[0].amount,
        Some("500".parse::<BigDecimal>().unwrap())
    );
}

#[sqlx::test(migrations = "../db/migrations", fixtures("details"))]
